WITH q1 AS ( SELECT cliente, ROUND(SUM(faturamento), 2) AS faturamento_q1 FROM itens WHERE mes BETWEEN '2026-01' AND '2026-03' GROUP BY cliente ), q2 AS ( SELECT cliente, ROUND(SUM(faturamento), 2) AS faturamento_q2 FROM itens WHERE mes BETWEEN '2026-04' AND '2026-06' GROUP BY cliente ) SELECT q1.cliente, q1.faturamento_q1, COALESCE(q2.faturamento_q2, 0) AS faturamento_q2, ROUND((COALESCE(q2.faturamento_q2, 0) - q1.faturamento_q1) * 100.0 / q1.faturamento_q1, 1) AS perc_change FROM q1 LEFT JOIN q2 ON q1.cliente = q2.cliente WHERE q1.faturamento_q1 <> 0 ORDER BY perc_change DESC;